<script setup>
import {computed,ref} from 'vue'
import {withBase} from 'vitepress'
import data from './project-screens.json'
const active=ref('all'),search=ref(''),limit=ref(12),dialog=ref(null),current=ref(null),origin=ref(null)
const screens=computed(()=>data.screens.filter(s=>(active.value==='all'||s.category===active.value)&&(!search.value.trim()||s.keywords.toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase()))))
function choose(value){active.value=value;limit.value=12}
function zoom(screen,event){origin.value=event.currentTarget;current.value=screen;dialog.value?.showModal()}
function close(){dialog.value?.close();origin.value?.focus()}
function move(delta){const list=screens.value;const i=list.findIndex(s=>s.id===current.value?.id);current.value=list[(i+delta+list.length)%list.length]}
const featured=[['1.7-image31','일정과 주공정'],['1.7-image32','보할과 누적 진도'],['1.8-image40','자원과 투입'],['1.9-image27','맞춤형 보고서']].map(([id,label])=>({...data.screens.find(s=>s.id===id),label}))
const faq=[['MS Project는 어떤 프로그램인가요?','작업의 기간·선후행 관계·달력과 자원·비용을 연결해 프로젝트를 계획하고 추적하며 보고하는 프로젝트 관리 프로그램입니다. 이 페이지는 Windows 데스크톱 Project의 활용을 중심으로 설명합니다.'],['Excel과 함께 사용할 수 있나요?','함께 활용할 수 있습니다. Project의 일정 관리와 Excel의 자료 취합·분석·공유 형식을 목적에 맞게 연결합니다. 데이터 교환 형식과 갱신 방식은 실제 버전과 조직의 관리 정책을 확인해 설계합니다.'],['Project Template은 무엇인가요?','업무에 필요한 필드·보기·필터·표·보고서와 운영 기준을 묶은 관리 틀입니다. 피엠오피스는 고객의 프로젝트 구조와 보고 요구에 맞게 구성하고 활용 방법을 인계합니다.'],['공정표만 작성하는 데 사용하나요?','일정뿐 아니라 자원·작업량·비용·진도와 보고에 활용할 수 있습니다. 적용 범위는 입력 데이터와 관리 기준, 사용하는 제품·버전에 따라 정합니다.'],['교육과 컨설팅은 어떻게 선택하나요?','직접 작성·운영하는 역량이 필요하면 교육을, 제출할 공정표나 조직 맞춤형 관리 체계가 필요하면 컨설팅을 검토하실 수 있습니다. 두 방식을 함께 구성할 수도 있습니다.']]
</script>
<template><main class="project-intro consulting marketing">
  <section class="project-intro-hero section-inner"><div><span class="consult-eyebrow">MICROSOFT PROJECT</span><h1 id="page-title"><span class="project-product-position">기업 프로젝트 공정 관리와 국가연구개발 사업 관리에 최적화된 최고의 전문성과 확장성을 가진 프로젝트 관리 전문 소프트웨어,</span> <strong>Microsoft Project</strong></h1><p>WBS·선후행 관계에 따른 공정 계획, 기준선 대비 진도·자원·비용 분석, 기관·기업별 맞춤 보고서까지. Microsoft Project와 Excel을 활용한 관리 방법을 실제 화면으로 확인하십시오.</p><div class="actions"><a class="btn primary" href="#project-gallery">화면으로 살펴보기 ↓</a><a class="btn secondary" :href="withBase('/consulting/pm.html')">컨설팅 알아보기 ↗</a></div></div><button type="button" class="project-hero-image" aria-label="MS Project 공정표 확대" @click="zoom(featured[0],$event)"><img :src="withBase(featured[0].thumb)" alt="MS Project 공정표와 누적 진도" :width="featured[0].width" :height="featured[0].height" fetchpriority="high"><span aria-hidden="true">↗</span></button></section>
  <section class="section-inner project-definition"><span class="consult-eyebrow">MS Project 활용 목적</span><h2>공정이 늦어지면 납기는 어떻게 달라질까요?<br>작업 간 선후행 관계와 변경 영향을 검토하십시오.</h2><p>설계가 늦어지면 조달과 시공은 어떻게 달라질까요? 특정 기간에 인력 투입이 몰린다면 어디를 조정해야 할까요? Microsoft Project는 작업의 연결과 자원·달력 조건을 일정에 반영하고, 계획과 실적을 비교할 수 있도록 돕습니다.</p><div class="project-flow"><span>작업 구조</span><b>→</b><span>일정·자원·비용</span><b>→</b><span>실적·변경</span><b>→</b><span>검토·보고</span></div></section>
  <section class="project-capabilities"><div class="section-inner"><span class="consult-eyebrow">주요 관리 기능</span><h2>무엇을 관리할 수 있나요?</h2><div class="project-capability-grid"><article v-for="(c,i) in data.categories" :key="c.id"><span class="consult-number">0{{i+1}}</span><h3>{{c.heading}}</h3><p>{{c.text}}</p><a :href="'#project-gallery'" @click="choose(c.id)">{{c.title}} 화면 보기 ↗</a></article></div></div></section>
  <section class="section-inner project-featured"><div class="project-featured-grid"><button v-for="s in featured" :key="s.id" type="button" :aria-label="s.label+' 화면 확대'" @click="zoom(s,$event)"><img :src="withBase(s.thumb)" :alt="s.alt" :width="s.width" :height="s.height" loading="lazy"><span aria-hidden="true">↗</span></button></div></section>
  <section id="project-gallery" class="section-inner project-gallery"><span class="consult-eyebrow">공정표·보고서 화면</span><h2>관리 목적에 맞는 화면을 찾아보세요.</h2><div class="project-gallery-controls"><div class="project-filters" role="group" aria-label="화면 분야"><button type="button" :aria-pressed="active==='all'" @click="choose('all')">전체</button><button v-for="c in data.categories" :key="c.id" type="button" :aria-pressed="active===c.id" @click="choose(c.id)">{{c.title}}</button></div><label class="project-search">화면 검색<input v-model="search" type="search" placeholder="예: 보할, 투입, 비용, 보고서" @input="limit=12"></label></div><p class="project-result" role="status">{{screens.length}}개 화면</p><div class="project-gallery-grid"><button v-for="s in screens.slice(0,limit)" :key="s.id" type="button" :aria-label="s.alt+' 확대 '+s.id" @click="zoom(s,$event)"><img :src="withBase(s.thumb)" :alt="s.alt" :width="s.width" :height="s.height" loading="lazy" decoding="async"><span aria-hidden="true">↗</span></button></div><p v-if="!screens.length">검색어를 바꾸거나 전체 분야를 선택해 주세요.</p><button v-if="limit<screens.length" type="button" class="btn secondary project-load" @click="limit+=12">화면 더 보기 ↓</button></section>
  <section class="project-excel"><div class="section-inner"><span class="consult-eyebrow">PROJECT × EXCEL</span><h2>공정 계획은 Microsoft Project로,<br>자료 취합·분석·보고는 Excel과 함께.</h2><p>참여 조직이 취합하는 자료와 PM이 관리하는 일정, 보고받는 사람이 원하는 형식을 연결합니다. 피엠오피스는 Microsoft Project와 Excel을 활용해 고객의 입력·갱신·분석·보고 체계를 함께 설계합니다.</p><div class="project-compare"><article><h3>Microsoft Project</h3><p>작업 구조 · 선후행 관계 · 달력 · 일정 계산<br>자원과 비용 · 기준선 · 현재 일정과 실적</p></article><article><h3>Microsoft Excel</h3><p>자료 취합 · 입력 양식 · 데이터 정리<br>분석과 공유 · 조직별 보고 형식</p></article></div></div></section>
  <section class="section-inner project-start"><span class="consult-eyebrow">교육·컨설팅 안내</span><h2>담당자 교육과<br>맞춤형 PM 컨설팅을 지원합니다.</h2><div class="project-start-grid"><a :href="withBase('/ms-project/index.html')"><h3>MS Project 교육 ↗</h3><p>핵심 실무부터 전문가·Template 개발까지</p></a><a :href="withBase('/consulting/pm.html')"><h3>PM 컨설팅 ↗</h3><p>EPC·연구개발·글로벌 기업의 관리 체계</p></a><a :href="withBase('/consulting/scheduling.html')"><h3>공정표 작성 대행 ↗</h3><p>입찰·발주처·감독기관 제출과 기업 통합 관리</p></a></div><div class="project-membership"><h3>컨설팅 관련 교재와 실무 자료를 평생 공유합니다.</h3><p>평생 멤버십으로 컨설팅 범위와 관련된 최신 교재, 다양한 모범 산출물과 심화 학습 자료를 지속적으로 공유합니다. 제공 대상·자료 범위는 계약에서 정하며, 추가 맞춤 개발과 컨설팅은 해당 범위를 협의합니다.</p></div></section>
  <section class="section-inner consult-faq"><span class="consult-eyebrow">FAQ</span><h2>MS Project, 시작 전 궁금한 점</h2><details v-for="f in faq" :key="f[0]"><summary>{{f[0]}}</summary><p>{{f[1]}}</p></details></section>
  <section class="section-inner project-sources"><h2>제품 기능과 활용 근거</h2><a href="https://support.microsoft.com/en-us/project/project-help" target="_blank" rel="noopener">Microsoft Project 공식 도움말 ↗</a><a href="https://support.microsoft.com/en-US/project/link-tasks-in-a-project" target="_blank" rel="noopener">작업 간 연결 ↗</a><a href="https://support.microsoft.com/en-us/project/create-or-update-a-baseline-or-an-interim-plan-in-project-desktop" target="_blank" rel="noopener">기준선과 추적 ↗</a><p>제품 설명은 Microsoft 공식 도움말, 활용 화면은 피엠오피스 Project Template 보기·보고서 개발 자료를 근거로 구성했습니다. 실제 적용 기능과 데이터 연계 방식은 사용 제품·버전·관리 요구를 확인합니다.</p></section>
  <dialog ref="dialog" class="project-screen-dialog" aria-label="MS Project 화면 확대" @cancel="origin?.focus()" @click="e=>e.target===dialog&&close()" @keydown.left.prevent="move(-1)" @keydown.right.prevent="move(1)"><div class="project-dialog-tools"><button type="button" aria-label="이전 화면" @click="move(-1)">←</button><button type="button" aria-label="다음 화면" @click="move(1)">→</button><button type="button" aria-label="화면 닫기" @click="close">닫기 ×</button></div><div class="project-dialog-scroll"><img v-if="current" :src="withBase(current.image)" :alt="current.alt" :width="current.width" :height="current.height"></div></dialog>
</main></template>
